const $=id=>document.getElementById(id),params=new URLSearchParams(location.search);
let map,renderer,markers,snapshot=null,index=[],extraOfficial=[],nationalData=null,viewport=[],foreign=[],selectedId=null,controller=null,requestId=0,moveTimer,foreignRequested=false;
const saved=new Map(),compared=new Map(),markerById=new Map();
let policyRegistry={},policyRatings={},policyRoutes={},routeController=null,routeTimer=null,routeVersion=0,routesPaused=false;
const routeAttempts=new Set();
try{for(const c of JSON.parse(localStorage.getItem('fri-atlas-saved-courses')||'[]'))if(c&&typeof c.id==='string'&&typeof c.name==='string'&&c.tags)saved.set(c.id,c);}catch{}
const currentCourse=id=>index.find(c=>c.id===id)||foreign.find(c=>c.id===id);
const eligibleSnapshot=c=>{const live=c&&currentCourse(c.id);return live&&isEligibleCourse(live)?{...c,eligibility:live.eligibility,evaluation:live.evaluation,routes:live.routes||c.routes,routeState:live.routeState||c.routeState}:null;};
const eligibleSaved=()=>[...saved.values()].map(eligibleSnapshot).filter(Boolean);
const eligibleCompared=()=>[...compared.values()].map(eligibleSnapshot).filter(Boolean);
const favorites=()=>new Set(eligibleSaved().map(c=>c.id));
const findCourse=id=>eligibleSnapshot(compared.get(id)||snapshot?.items.find(c=>c.id===id)||currentCourse(id)||saved.get(id));
const bounds=()=>{const b=map.getBounds();return {s:b.getSouth(),w:b.getWest(),n:b.getNorth(),e:b.getEast()};};
const sameBounds=(a,b)=>a&&['s','w','n','e'].every(k=>Math.abs(a[k]-b[k])<.00001);
const number=(key,fallback,min,max)=>{const n=Number(params.get(key));return params.has(key)&&Number.isFinite(n)&&n>=min&&n<=max?n:fallback;};
const options=()=>({search:$('searchInput').value,sort:$('sortSelect').value,limit:Number($('limitSelect').value),favorites:$('favoriteOnly').checked?favorites():null});
const chosen=()=>snapshot?shortList(snapshot.items,options()):[];
const cardOptions=()=>({favorites:favorites(),compared:new Set(compared.keys()),selectedId,sort:options().sort});
const time=()=>new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' KST';
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
function updateNavigator(){if(!map)return;const b=bounds();$('zoomText').textContent=`ZOOM ${map.getZoom()}`;$('visibleCount').textContent=viewport.length;$('snapshotCount').textContent=snapshot?.items.length??'—';$('displayCount').textContent=chosen().length;$('displayLimit').textContent=`분석 목록 / 최대 ${options().limit}`;$('boundsText').textContent=`현재 S ${b.s.toFixed(3)} / W ${b.w.toFixed(3)} / N ${b.n.toFixed(3)} / E ${b.e.toFixed(3)}`;$('navDetail').textContent=`지도 ${viewport.length}개 마커 · TOP 상한과 무관 · 18홀 이상 확인 ${index.length}개 / 원천 ${nationalData?.courses?.length??1119}객체 · 홀수/유형 미확인 제외`;
if(snapshot){const q=snapshot.bounds;$('lastAnalysis').textContent=`분석 ${snapshot.time}\nS ${q.s.toFixed(3)} / W ${q.w.toFixed(3)} / N ${q.n.toFixed(3)} / E ${q.e.toFixed(3)} · ${sameBounds(q,b)?'현재 영역':'이전 영역'}\n후보 ${snapshot.items.length} · 목록 ${chosen().length} · 나머지 ${Math.max(0,snapshot.items.length-chosen().length)} · 18홀 이상 정규 코스만 표시\n경로: ${snapshot.routing?.message||'미조회'}`;}else $('lastAnalysis').textContent='지도 정지 → 전체 마커 갱신 / ANALYSIS → 비교 목록 고정';}
function selectCourse(id,{pan=false}={}){const c=findCourse(id);if(!c)return;selectedId=id;if(pan&&map)map.setView([c.lat,c.lon],Math.max(map.getZoom(),11));$('selectedCourse').hidden=false;$('selectedCourse').innerHTML='<div class="section-title"><span>MAP SELECTION</span><button class="text-button" data-close-selection>닫기 ×</button></div>'+card(c,0,cardOptions());renderResults();for(const marker of markerById.values())marker.setStyle({radius:5,fillColor:'#247352',color:'#fff'});const m=markerById.get(id);if(m){m.setStyle({radius:10,fillColor:'#deef63',color:'#163f35'});m.openTooltip();}const el=[...$('results').querySelectorAll('[data-course]')].find(el=>el.dataset.course===id);el?.scrollIntoView({block:'nearest',behavior:'auto'});}
function renderMap(){if(!map)return;markers.clearLayers();markerById.clear();viewport=viewportCourses(mergeById(index,foreign),bounds());for(const c of viewport){const m=L.circleMarker([c.lat,c.lon],{renderer,radius:c.id===selectedId?9:5,color:'#fff',weight:1.5,fillColor:c.id===selectedId?'#deef63':'#247352',fillOpacity:.9});const label=document.createElement('span');label.textContent=c.name;m.bindTooltip(label,{direction:'top',permanent:showMapNames(viewport.length),className:'course-map-label',opacity:1}).on('click',()=>selectCourse(c.id)).addTo(markers);markerById.set(c.id,m);}updateNavigator();}
function renderResults(){if(!snapshot)return;const items=chosen();$('results').innerHTML=items.length?items.map((c,i)=>card(c,i,cardOptions())).join(''):'<div class="empty-state"><h3>18홀 이상 확인 자료가 없습니다.</h3><p>이 영역에 골프장이 없다는 뜻은 아닙니다. 홀수·정규 코스 유형이 확인된 자료만 표시합니다.</p></div>';$('downloadButton').disabled=false;$('mailButton').disabled=false;updateNavigator();renderCompare();scheduleRoutes();}
function renderSaved(){const items=eligibleSaved();$('savedResults').innerHTML=items.length?items.map((c,i)=>card(c,i,cardOptions())).join(''):'<p class="catalog-note">♡를 누르면 저장 당시 자료를 이 브라우저에 보관합니다. 현재 18홀 이상 정규 코스로 확인된 저장 항목만 표시합니다.</p>';}
function renderCompare(){const items=eligibleCompared();$('compareTray').innerHTML=compareTable(items,$('playDate').value,Number($('partySize').value));$('compareCount').textContent=`${items.length}/4`;}
function rerender(){renderResults();renderSaved();renderCompare();$('catalogResults').innerHTML=extraOfficial.map((c,i)=>card(c,i,cardOptions())).join('');if(selectedId){const c=findCourse(selectedId);if(c)$('selectedCourse').innerHTML='<div class="section-title"><span>MAP SELECTION</span><button class="text-button" data-close-selection>닫기 ×</button></div>'+card(c,0,cardOptions());}}
function cancel(){requestId++;controller?.abort();controller=null;clearTimeout(routeTimer);routeVersion++;routeController?.abort();routeController=null;for(const c of [...index,...foreign])if(c.routeState==='loading')syncRoutes(c.id,null,'failed');$('analyzeButton').disabled=false;$('cancelButton').hidden=true;}
function routeTargets(){return mergeById(chosen(),eligibleCompared()).filter(c=>!routeAttempts.has(c.id)&&!(c.routes?.seoul&&c.routes?.busan)).slice(0,20);}
function syncRoutes(id,routes,routeState){const collections=[index,foreign,snapshot?.items||[],[...saved.values()],[...compared.values()]];for(const collection of collections)for(const c of collection)if(c.id===id){if(routes&&Object.keys(routes).length)c.routes={...c.routes,...routes};c.routeState=routeState;}}
function scheduleRoutes(){if(routesPaused||!snapshot||!routeTargets().length)return;clearTimeout(routeTimer);routeTimer=setTimeout(()=>loadVisibleRoutes(requestId),350);}
async function loadVisibleRoutes(analysisId){if(analysisId!==requestId||routeController)return;const targets=routeTargets();if(!targets.length)return;const version=++routeVersion,aborter=new AbortController();routeController=aborter;for(const c of targets){routeAttempts.add(c.id);syncRoutes(c.id,null,'loading');}rerender();const timer=setTimeout(()=>aborter.abort(),25000);try{const outcome=await resolveRouting(targets,{signal:aborter.signal,fetcher:fetchRoads});if(analysisId!==requestId||version!==routeVersion)return;for(const c of targets){const routes=outcome.routes.get(c.id);syncRoutes(c.id,routes,routes?.seoul&&routes?.busan?'success':['failed','timeout'].includes(outcome.state)?'failed':'unavailable');}snapshot.routing={state:outcome.state,count:outcome.count,message:outcome.message};snapshot.routeCoverage=snapshot.items.filter(c=>c.routes?.seoul&&c.routes?.busan).length;rerender();const notice=analysisNotice({count:snapshot.items.length,limit:options().limit,sortLabel:$('sortSelect').selectedOptions[0].textContent,routing:snapshot.routing});status(notice.text,notice.error);}finally{clearTimeout(timer);if(version===routeVersion){routeController=null;scheduleRoutes();}}}
async function analyze(runRouting=true){if(!map||!index.length){status('전국 자료를 먼저 불러와 주세요.',true);return;}cancel();routesPaused=false;routeAttempts.clear();const id=++requestId,b={...bounds()};if(!validBounds(b)){status('날짜변경선·세계 반복영역은 지원하지 않습니다.',true);return;}controller=new AbortController();$('analyzeButton').disabled=true;$('cancelButton').hidden=false;status('이 화면의 후보를 비교 목록으로 정리하는 중…');try{let items=viewportCourses(mergeById(index,foreign),b);const center=map.getCenter(),outsideKorea=center.lat<32||center.lat>40||center.lng<123||center.lng>133;if(!items.length&&outsideKorea){if(foreignRequested)throw new Error('해외 실험 조회는 페이지당 1회입니다. 한국 지도로 돌아가세요.');const query=queryFor(b);foreignRequested=true;const aborter=controller;const timer=setTimeout(()=>aborter.abort(),35000);try{const response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams({data:query}),signal:aborter.signal});if(!response.ok)throw new Error(`해외 검색 서버 ${response.status}`);const data=await response.json();if(data.remark||!Array.isArray(data.elements))throw new Error('해외 검색 결과가 불완전합니다.');if(id!==requestId)return;items=applyCoursePolicy(normalize(data.elements,b).map(c=>({...c,id:'osm:'+c.id,sourceUrl:'https://www.openstreetmap.org/'+c.id})),policyRegistry,policyRatings,policyRoutes);foreign=mergeById(foreign,items);}finally{clearTimeout(timer);}}
await new Promise(resolve=>requestAnimationFrame(resolve));if(id!==requestId)return;snapshot={bounds:b,time:time(),dataTime:nationalData?.generatedAt,provider:outsideKorea?'overseas-experimental':'national-snapshot',rawCount:index.length,items:structuredClone(items)};const cachedCount=chosen().filter(c=>c.routes?.seoul&&c.routes?.busan).length;snapshot.routing={state:cachedCount===chosen().length&&cachedCount>0?'success':'pending',count:cachedCount,message:cachedCount?`서울·부산 도로 기록 ${cachedCount}/${chosen().length}곳 · 수집일은 각 경로 출처 참고`:'서울·부산 도로 자동 조회 대기'};snapshot.routeCoverage=cachedCount;renderResults();renderMap();if(runRouting&&chosen().length)await loadVisibleRoutes(id);if(id!==requestId)return;const notice=analysisNotice({count:items.length,limit:options().limit,sortLabel:$('sortSelect').selectedOptions[0].textContent,routing:snapshot.routing});status(notice.text,notice.error);updateNavigator();}catch(error){if(id===requestId)status(error.name==='AbortError'?'분석 취소 또는 시간초과 · 이전 결과 유지':error.message,true);}finally{if(id===requestId){controller=null;$('analyzeButton').disabled=false;$('cancelButton').hidden=true;}}}
function persist(){try{localStorage.setItem('fri-atlas-saved-courses',JSON.stringify([...saved.values()]));localStorage.setItem('fri-atlas-favorites',JSON.stringify([...saved.keys()]));}catch{status('브라우저 저장 불가 · 현재 화면에서만 유지합니다.',true);}}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.closeSelection!==undefined){$('selectedCourse').hidden=true;selectedId=null;return;}const id=b.dataset.map||b.dataset.favorite||b.dataset.compare;if(!id)return;const c=findCourse(id);if(!c)return;if(b.dataset.map)selectCourse(id,{pan:true});else if(b.dataset.favorite){saved.has(id)?saved.delete(id):saved.set(id,structuredClone(c));persist();rerender();}else{const adding=!compared.has(id);if(compared.has(id))compared.delete(id);else if(compared.size<4)compared.set(id,structuredClone(c));else{status('비교는 최대 4곳입니다. 먼저 한 곳을 빼 주세요.',true);return;}rerender();if(adding){const panel=$('planningPanel');panel.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(event.detail===0)panel.focus({preventScroll:true});}}});
document.addEventListener('error',event=>{const img=event.target;if(img instanceof HTMLImageElement){img.hidden=true;const fallback=img.nextElementSibling;if(fallback)fallback.hidden=false;}},true);
function shareURL(){const u=new URL(location.href),c=map?.getCenter();u.search='';if(c){u.searchParams.set('lat',c.lat.toFixed(5));u.searchParams.set('lon',c.lng.toFixed(5));u.searchParams.set('z',map.getZoom());}for(const [key,value]of Object.entries({sort:$('sortSelect').value,limit:options().limit,q:$('searchInput').value,date:$('playDate').value,party:$('partySize').value}))if(value!=='')u.searchParams.set(key,value);return u.href;}
$('analyzeButton').onclick=()=>analyze(true);$('cancelButton').onclick=()=>{routesPaused=true;cancel();rerender();status('분석 취소 · 이전 결과 유지');};$('koreaButton').onclick=()=>map?.fitBounds([[33,124.5],[38.7,131]]);
$('clearCompare').onclick=()=>{compared.clear();rerender();};for(const id of ['searchInput','sortSelect','limitSelect','favoriteOnly'])$(id).addEventListener(id==='searchInput'?'input':'change',renderResults);for(const id of ['playDate','partySize'])$(id).addEventListener('change',renderCompare);
$('shareButton').onclick=async()=>{try{await navigator.clipboard.writeText(shareURL());status('화면 링크를 복사했습니다.');}catch{status('아래 링크를 선택해 복사하세요.');const input=document.createElement('input');input.value=shareURL();input.readOnly=true;$('status').append(input);input.select();}};
$('downloadButton').onclick=()=>{if(!snapshot)return;const html=exportReport(snapshot,chosen(),{date:$('playDate').value,partySize:Number($('partySize').value),compareCourses:eligibleCompared(),sortLabel:$('sortSelect').selectedOptions[0].textContent,limit:options().limit});const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='FRI-ATLAS-'+new Date().toISOString().slice(0,10)+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);status('HTML을 저장했습니다. 메일에 직접 첨부하세요.');};
$('mailButton').onclick=()=>{location.href=`mailto:?subject=${encodeURIComponent('FRI ATLAS / 골프장 비교')}&body=${encodeURIComponent('골프장 비교 자료를 공유합니다.\n'+shareURL()+'\n분석 '+snapshot.time+'\n저장한 HTML은 직접 첨부해 주세요. 요금은 실시간 견적이 아닙니다.')}`;};
$('aboutButton').onclick=()=>$('aboutDialog').showModal();$('closeAbout').onclick=()=>$('aboutDialog').close();
async function init(){renderSaved();if(!window.L){status('지도를 불러오지 못했습니다. 연결을 확인하세요.',true);return;}map=L.map('map',{minZoom:3,maxZoom:18,maxBounds:[[-85,-180],[85,180]],preferCanvas:true}).setView([number('lat',36.35,-80,80),number('lon',127.7,-180,180)],number('z',7,3,18));if(!params.has('lat'))map.fitBounds([[33,124.5],[38.7,131]]);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);renderer=L.canvas({padding:.3});markers=L.layerGroup().addTo(map);const settled=createDebouncer(()=>{$('motionState').textContent='CATCH';$('motionState').classList.remove('explorer');renderMap();},300);map.on('movestart',()=>{settled.cancel();$('motionState').textContent='EXPLORER';$('motionState').classList.add('explorer');});map.on('moveend',()=>settled.trigger());
try{const [nr,cr,er,mr,fr,sr,pr,rr,tr]=await Promise.all([fetch('./courses-kr.json?v=20261023-5'),fetch('./catalog.json?v=20261023-5'),fetch('./enrichment-v2.json?v=20261023-5'),fetch('./explicit-matches.json?v=20261023-5'),fetch('./v3-fees.json?v=20261023-5'),fetch('./v3-course-stories.json?v=20261023-5'),fetch('./regular-courses.json?v=20261023-5'),fetch('./ratings.json?v=20261023-5'),fetch('./road-cache.json?v=20261023-5')]);if(!nr.ok)throw new Error('전국 골프장 자료를 불러오지 못했습니다.');nationalData=await nr.json();if(!pr.ok)throw new Error('18홀 이상 정규 코스 확인 자료를 불러오지 못했습니다.');policyRegistry=await pr.json();policyRatings=rr.ok?await rr.json():{};policyRoutes=tr.ok?await tr.json():{};const catalogData=cr.ok?await cr.json():{courses:[]};const mapping=mr.ok?await mr.json():{};const enriched=enrichOfficial(normalizeNational(nationalData),catalogData,mapping);const enrichment=er.ok?await er.json():{};const fees=fr.ok?await fr.json():{},stories=sr.ok?await sr.json():{};index=applyCoursePolicy(applyV3(applyEnrichment(enriched.items,enrichment),fees,stories),policyRegistry,policyRatings,policyRoutes);extraOfficial=applyCoursePolicy(applyV3(applyEnrichment(enriched.unmatched,enrichment),fees,stories).map(c=>({...c,sourceUrl:c.official?.name?.source_url})),policyRegistry,policyRatings,policyRoutes);index=mergeById(index,extraOfficial);$('catalogResults').innerHTML=extraOfficial.map((c,i)=>card(c,i,cardOptions())).join('');$('coverageText').textContent=`18홀 이상 정규 코스 확인 ${index.length}곳 / 원천 ${nationalData.courses?.length??1119}객체 · 연습장·9홀·홀수/유형 미확인 제외 · 전국 골프장 전체 확보는 아닙니다.`;renderSaved();renderMap();analyze(true);}catch(error){status(error.message,true);}}
if(['recommended','evaluation','weekday','weekend','seoul','busan','name'].includes(params.get('sort')))$('sortSelect').value=params.get('sort');if(params.get('limit')==='20')$('limitSelect').value='20';$('searchInput').value=(params.get('q')||'').slice(0,100);if(/^\d{4}-\d{2}-\d{2}$/.test(params.get('date')||''))$('playDate').value=params.get('date');if(['1','2','3','4'].includes(params.get('party')))$('partySize').value=params.get('party');
if(document.readyState==='complete')init();else window.addEventListener('load',init,{once:true});
